-- =================================================================
-- MIGRATION: ATUALIZAR PARQUE DE EQUIPAMENTOS (OUTUBRO 2026)
-- Registros: 399 equipamentos sincronizados e normalizados
-- Execute este script no Supabase Dashboard > SQL Editor
-- =================================================================

-- 1. Adicionar novas colunas se ainda não existirem
ALTER TABLE equipamentos ADD COLUMN IF NOT EXISTS status_conexao VARCHAR(50);
ALTER TABLE equipamentos ADD COLUMN IF NOT EXISTS latencia_ms INTEGER;
ALTER TABLE equipamentos ADD COLUMN IF NOT EXISTS ultimo_ping TIMESTAMP;
ALTER TABLE equipamentos ADD COLUMN IF NOT EXISTS status_instalacao VARCHAR(50);
ALTER TABLE equipamentos ADD COLUMN IF NOT EXISTS contato_responsavel VARCHAR(255);
ALTER TABLE equipamentos ADD COLUMN IF NOT EXISTS contato_telefone VARCHAR(100);
ALTER TABLE equipamentos ADD COLUMN IF NOT EXISTS contato_ramal VARCHAR(100);
ALTER TABLE equipamentos ADD COLUMN IF NOT EXISTS contato_email VARCHAR(255);

-- 2. Garantir índice UNIQUE no campo codigo para upsert
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint WHERE conname = 'equipamentos_codigo_key'
    ) THEN
        ALTER TABLE equipamentos ADD CONSTRAINT equipamentos_codigo_key UNIQUE (codigo);
    END IF;
END $$;

-- 3. Liberar RLS para que o sistema e futuros uploads funcionem
ALTER TABLE equipamentos ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "equipamentos_all_access" ON equipamentos;
CREATE POLICY "equipamentos_all_access" ON equipamentos FOR ALL USING (true) WITH CHECK (true);

