-- 5. Criar função RPC para importações visuais futuras diretamente pelo navegador
CREATE OR REPLACE FUNCTION upsert_equipamentos_json(p_equipamentos JSONB)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  elem JSONB;
  v_count INTEGER := 0;
BEGIN
  FOR elem IN SELECT * FROM jsonb_array_elements(p_equipamentos)
  LOOP
    INSERT INTO equipamentos (
      codigo, nome, modulo, ip_equipamento, secretaria, endereco, cep, 
      latitude, longitude, status_conexao, latencia_ms, ultimo_ping, status_instalacao
    ) VALUES (
      (elem->>'codigo')::INTEGER,
      elem->>'nome',
      NULLIF(elem->>'modulo', '')::INTEGER,
      elem->>'ip_equipamento',
      elem->>'secretaria',
      elem->>'endereco',
      elem->>'cep',
      NULLIF(elem->>'latitude', '')::NUMERIC,
      NULLIF(elem->>'longitude', '')::NUMERIC,
      elem->>'status_conexao',
      NULLIF(elem->>'latencia_ms', '')::INTEGER,
      NULLIF(elem->>'ultimo_ping', '')::TIMESTAMP,
      elem->>'status_instalacao'
    )
    ON CONFLICT (codigo) DO UPDATE SET
      nome = EXCLUDED.nome,
      modulo = EXCLUDED.modulo,
      ip_equipamento = EXCLUDED.ip_equipamento,
      secretaria = EXCLUDED.secretaria,
      endereco = EXCLUDED.endereco,
      cep = EXCLUDED.cep,
      latitude = EXCLUDED.latitude,
      longitude = EXCLUDED.longitude,
      status_conexao = EXCLUDED.status_conexao,
      latencia_ms = EXCLUDED.latencia_ms,
      ultimo_ping = EXCLUDED.ultimo_ping,
      status_instalacao = EXCLUDED.status_instalacao,
      updated_at = NOW();
    v_count := v_count + 1;
  END LOOP;
  RETURN jsonb_build_object('success', true, 'total_processado', v_count);
END;
$$;

SELECT COUNT(*) AS total_equipamentos_atualizados FROM equipamentos;